  // --- Background Summary Generator (Sequential with Mask) ---
  const runBackgroundSummaryCheck = useCallback(async (cardsToCheck: BusinessCardData[]) => {
    const missingSummary = cardsToCheck.filter(c => !c.summary || c.summary.trim() === '');

    if (missingSummary.length > 0) {
        console.log(`Found ${missingSummary.length} cards without summary. Auto-generating sequentially...`);
        setIsAutoSummarizing(true);
        setAutoSummaryProgress({ current: 0, total: missingSummary.length });

        let processedCount = 0;

        // Process sequentially to be gentle on API limits and avoid concurrency issues
        for (const card of missingSummary) {
            try {
                // Fetch full card data if needed (if card is metadata only)
                // But generally text should be in metadata.

                // Add a small delay between requests
                await new Promise(r => setTimeout(r, 800));

                const summary = await generateSummaryFromText(card);
                if (summary) {
                    const updatedCard = { ...card, summary };
                    await saveCardToDB(updatedCard);

                    // Update state safely
                    setCards(prev => prev.map(c => c.id === card.id ? { ...c, summary } : c));

                    // If current form is this card, update it too
                    setFormData(prev => prev && prev.id === card.id ? { ...prev, summary } : prev);
                }
            } catch (e) {
                console.warn(`Failed to auto-generate summary for ${card.id}`, e);
            } finally {
                processedCount++;
                setAutoSummaryProgress(prev => ({ ...prev, current: processedCount }));
            }
        }

        // Brief delay before removing mask so user sees completion
        await new Promise(r => setTimeout(r, 500));
        setIsAutoSummarizing(false);
    }
  }, []);

