                                       <button onClick={() => setCropperTransform(t => ({...t, scale: t.scale + 0.2}))} className="w-8 h-8 text-slate-500 hover:bg-white rounded"><i className="fa-solid fa-plus text-xs"></i></button>
                                   </div>

                                   {/* Rotate Controls (New) */}
