import { GoogleGenAI, Type } from "@google/genai";
import { BusinessCardData } from "../types";

const sleep = (ms: number) => new Promise(resolve => setTimeout(resolve, ms));

const cleanJsonText = (text: string): string => {
  text = text.trim();
  if (text.startsWith('```json')) {
    text = text.replace(/^```json\s*/, '').replace(/\s*```$/, '');
  } else if (text.startsWith('```')) {
    text = text.replace(/^```\s*/, '').replace(/\s*```$/, '');
  }
  return text;
};

/**
 * 通用 API 請求執行器
 * 功能：
 * 1. 自動重試 (Retry) 機制：針對 429 (Rate Limit) 與 5xx 錯誤進行指數退避重試。
 * 2. 權限錯誤處理：針對 403/Key 錯誤，若環境支援則提示切換金鑰。
 */
const executeWithFallback = async <T>(
  operation: (ai: GoogleGenAI) => Promise<T>,
  retryCount = 0,
  maxRetries = 3
): Promise<T> => {
  // 1. 初始化 AI 實例
  let ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    return await operation(ai);
  } catch (error: any) {
    const errorMessage = (error?.message || JSON.stringify(error)).toLowerCase();

    // 判斷錯誤類型
    const isRateLimit = errorMessage.includes("429") || errorMessage.includes("resource exhausted") || errorMessage.includes("quota");
    const isServerError = errorMessage.includes("500") || errorMessage.includes("503") || errorMessage.includes("internal");
    const isAuthError = errorMessage.includes("403") || errorMessage.includes("permission denied") || errorMessage.includes("api key") || errorMessage.includes("requested entity was not found");

    // 2. 針對 Rate Limit (429) 或 Server Error (5xx) 進行自動重試 (適合免費版 Key)
    if ((isRateLimit || isServerError) && retryCount < maxRetries) {
      const waitTime = 2000 * Math.pow(1.5, retryCount); // 指數退避: 2s, 3s, 4.5s
      console.warn(`API Busy/Error (${errorMessage}). Retrying in ${waitTime}ms... (Attempt ${retryCount + 1}/${maxRetries})`);
      await sleep(waitTime);
      return executeWithFallback(operation, retryCount + 1, maxRetries);
    }

    // 3. 只有在發生「權限/金鑰錯誤 (403)」時，才嘗試切換 Key (若環境支援)
    // 注意：不再對 429 錯誤強制切換 Key，讓免費版用戶可以等待重試
    if (isAuthError && (window as any).aistudio) {
      console.warn("API Auth Error. Attempting to switch Key...");
      try {
        await (window as any).aistudio.openSelectKey();
        ai = new GoogleGenAI({ apiKey: process.env.API_KEY }); // Update Key
        return await operation(ai);
      } catch (fallbackError) {
        console.error("Key switch failed:", fallbackError);
        throw error;
      }
    }

    throw error;
  }
};

/**
 * [單筆] 針對已有文字資料但缺少簡介的名片，生成摘要
 */
export const generateSummaryFromText = async (card: Partial<BusinessCardData>): Promise<string> => {
    try {
        const prompt = `
        請根據以下名片資訊，撰寫一段「精簡專業」的介紹文 (約 50-100 字，繁體中文)。

        【資訊】：
        姓名: ${card.lastName}${card.firstName}
        公司: ${card.company}
        職稱: ${card.title}
        部門: ${card.department || ''}
        產業: ${card.industry || ''}
        備註: ${card.notes || ''}

        【撰寫要求】：
        1. 介紹此人的姓名與現職。
        2. 根據職稱與公司性質，用一句話簡單點出其專業角色。
        3. 語氣需專業、流暢，適合商務場景。
        4. **重要規則：若資訊有缺漏，請直接省略，嚴禁在文中提及「未提供」、「未知」或顯示空白標籤**。
        5. 直接回傳純文字，不需標題。
        `;

        const response = await executeWithFallback(async (ai) => {
            return await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: { parts: [{ text: prompt }] }
            });
        });

        return response.text?.trim() || "";
    } catch (e) {
        console.warn("Text summary generation failed:", e);
        return "";
    }
};

/**
 * [批次] 針對多筆名片生成摘要 (大幅節省 Token 與請求次數)
 */
export const generateBatchSummaries = async (cards: Partial<BusinessCardData>[]): Promise<{id: string, summary: string}[]> => {
    if (cards.length === 0) return [];

    try {
        const simplifiedData = cards.map(c => ({
            id: c.id,
            name: `${c.lastName}${c.firstName}`,
            company: c.company,
            title: c.title,
            department: c.department || '',
            industry: c.industry || '',
            notes: c.notes || ''
        }));

        const prompt = `
        你是專業的名片分析師。請為以下 JSON 陣列中的每一筆名片資料，生成一段「精簡專業」的介紹文 (約 50-80 字，繁體中文)。

        【輸入資料 (JSON)】:
        ${JSON.stringify(simplifiedData)}

        【撰寫要求】：
        1. 針對每一筆資料生成 summary。
        2. 結構：介紹 [姓名] 為 [公司] 的 [職稱]，並根據其角色簡單描述。
        3. **若資訊有缺漏，直接省略該部分，嚴禁出現「未提供」等字眼**。
        4. 請回傳一個 JSON Array，格式為: [{"id": "對應ID", "summary": "介紹文"}, ...]
        `;

        const response = await executeWithFallback(async (ai) => {
            return await ai.models.generateContent({
                model: 'gemini-3-flash-preview',
                contents: { parts: [{ text: prompt }] },
                config: {
                    responseMimeType: "application/json",
                    responseSchema: {
                        type: Type.ARRAY,
                        items: {
                            type: Type.OBJECT,
                            properties: {
                                id: { type: Type.STRING },
                                summary: { type: Type.STRING }
                            },
                            required: ["id", "summary"]
                        }
                    }
                }
            });
        });

        const text = response.text;
        if (!text) return [];
        return JSON.parse(cleanJsonText(text));

    } catch (e) {
        console.warn("Batch summary generation failed:", e);
        return [];
    }
};

/**
 * 提取名片詳細資料
 */
export const extractCardInfo = async (
  base64Image: string, 
  mimeType: string = 'image/jpeg'
): Promise<any> => {
  const model = 'gemini-3-flash-preview';

  try {
    // executeWithFallback now handles retries (including 429) internally
    const response = await executeWithFallback(async (ai) => {
      return await ai.models.generateContent({
        model,
        contents: {
          parts: [
            {
              inlineData: {
                mimeType: mimeType,
                data: base64Image,
              },
            },
            {
              text: `你是一位專業的名片資料分析專家，專門為 QS Hub 系統處理全球名片。

【嚴格規則】：
1. **絕對忠於原圖**：僅提取名片上「肉眼可見」的文字資訊。若名片上沒有該資訊，請留空，嚴禁自行推測。
2. **語言處理**：
   - **英文/中文名片**：若名片包含英文，主要欄位請「優先提取英文」。若僅有中文，則提取中文。
   - **非中英名片**：若名片主要語言為**非中文且非英文**，請**直接提取名片上的原文**。
3. **店家/通用名片**：若該圖片是店家、餐廳或企業的通用名片，請務必將 firstName, lastName, title, prefix **全部留空 ("")**。
4. **分類強制規則**：若無法提取出 **lastName (姓氏)**，代表此名片無法歸戶到特定人士，請務必將 category 設定為 **'other'**。

【多重資料提取規則】：
- **電話 (Phone)**：請提取名片上「所有」可見的**電話、手機、公司總機**號碼。若有多組，請用 " / " 分隔。**不要包含傳真號碼**。
