// --- Tour Component ---
interface TourStep {
    targetId: string;
    title: string;
    content: string;
    position: 'right' | 'bottom' | 'bottom-left' | 'bottom-right' | 'top' | 'left';
}

const TourOverlay: React.FC<{ 
    stepIndex: number; 
    steps: TourStep[]; 
    onNext: () => void; 
    onSkip: () => void; 
}> = ({ stepIndex, steps, onNext, onSkip }) => {
    const [targetRect, setTargetRect] = useState<DOMRect | null>(null);
    const currentStep = steps[stepIndex];

    useEffect(() => {
        const updateRect = () => {
            const el = document.getElementById(currentStep.targetId);
            if (el) {
                setTargetRect(el.getBoundingClientRect());
                // Scroll into view if needed
                el.scrollIntoView({ behavior: 'smooth', block: 'center' });
            }
        };
        // Initial delay to allow layout to settle
        const timer = setTimeout(updateRect, 100);
        window.addEventListener('resize', updateRect);
        return () => {
            window.removeEventListener('resize', updateRect);
            clearTimeout(timer);
        };
    }, [stepIndex, currentStep.targetId]);

    if (!targetRect) return null;

    // --- Tooltip Positioning Logic ---
    let tooltipStyle: React.CSSProperties = {};
    const gap = 20;

    // Default fallback values
    let top = window.innerHeight / 2;
    let left = window.innerWidth / 2;

    switch (currentStep.position) {
        case 'right':
            top = targetRect.top;
            left = targetRect.right + gap;
            break;
        case 'left':
            top = targetRect.top;
            left = targetRect.left - 320 - gap; 
            break;
        case 'bottom':
            top = targetRect.bottom + gap;
            left = targetRect.left + (targetRect.width / 2) - 160;
            break;
        case 'bottom-left':
            top = targetRect.bottom + gap;
            left = targetRect.left;
            break;
        case 'bottom-right':
            top = targetRect.bottom + gap;
            left = targetRect.right - 320;
            break;
        case 'top':
            top = targetRect.top - 200; 
            left = targetRect.left + (targetRect.width / 2) - 160;
            break;
    }

    // Boundary checks
    if (left < 10) left = 10;
    if (left + 320 > window.innerWidth) left = window.innerWidth - 330;
    if (top < 10) top = 10;
    if (top + 150 > window.innerHeight) top = window.innerHeight - 160;

    tooltipStyle = { top, left };

    // --- Smart Hand Positioning Logic (Boundary Aware) ---

    // 1. Identify Text Side
    let textSide = 'bottom';
    if (currentStep.position === 'top') textSide = 'top';
    if (currentStep.position === 'left') textSide = 'left';
    if (currentStep.position === 'right') textSide = 'right';

    // 2. Default Preferred Hand Side (Opposite to Text)
    let handSide = 'top';
    if (textSide === 'bottom') handSide = 'top';
    if (textSide === 'top') handSide = 'bottom';
    if (textSide === 'left') handSide = 'right';
    if (textSide === 'right') handSide = 'left';

    // 3. Boundary & Collision Check
    const H_OFFSET = 90; // Approx px needed for hand
    const V_OFFSET = 90; 

    const canPlaceTop = targetRect.top > V_OFFSET;
    const canPlaceBottom = (window.innerHeight - targetRect.bottom) > V_OFFSET;
    const canPlaceLeft = targetRect.left > H_OFFSET;
    const canPlaceRight = (window.innerWidth - targetRect.right) > H_OFFSET;

    // Fallback logic: If preferred side is clipped, try perpendicular sides that don't overlap text
    if (handSide === 'top' && !canPlaceTop) {
        if (canPlaceLeft && textSide !== 'left') handSide = 'left';
        else if (canPlaceRight && textSide !== 'right') handSide = 'right';
        else if (canPlaceBottom && textSide !== 'bottom') handSide = 'bottom';
    } 
    else if (handSide === 'bottom' && !canPlaceBottom) {
        if (canPlaceLeft && textSide !== 'left') handSide = 'left';
        else if (canPlaceRight && textSide !== 'right') handSide = 'right';
        else if (canPlaceTop && textSide !== 'top') handSide = 'top';
    }
    else if (handSide === 'left' && !canPlaceLeft) {
        if (canPlaceBottom && textSide !== 'bottom') handSide = 'bottom';
        else if (canPlaceTop && textSide !== 'top') handSide = 'top';
        else if (canPlaceRight && textSide !== 'right') handSide = 'right';
    }
    else if (handSide === 'right' && !canPlaceRight) {
        if (canPlaceBottom && textSide !== 'bottom') handSide = 'bottom';
        else if (canPlaceTop && textSide !== 'top') handSide = 'top';
        else if (canPlaceLeft && textSide !== 'left') handSide = 'left';
    }

    // 4. Generate Styles
    let handEmoji = '👇';
    let handStyle: React.CSSProperties = {};
    let handClass = "absolute text-5xl z-50 drop-shadow-lg transition-all duration-300";

    switch (handSide) {
        case 'left':
             handEmoji = '👉';
             handStyle = { top: '50%', left: '-4.5rem', marginTop: '-1.5rem' }; 
             handClass += " animate-h-bounce"; 
             break;
        case 'right':
             handEmoji = '👈';
             handStyle = { top: '50%', right: '-4.5rem', marginTop: '-1.5rem' };
             handClass += " animate-h-bounce"; 
             break;
        case 'bottom':
             handEmoji = '👆';
             handStyle = { bottom: '-4.5rem', left: '50%', marginLeft: '-1.5rem' };
             handClass += " animate-bounce";
             break;
        case 'top':
        default:
             handEmoji = '👇';
             handStyle = { top: '-4.5rem', left: '50%', marginLeft: '-1.5rem' };
             handClass += " animate-bounce";
             break;
    }

    return (
        <div className="fixed inset-0 z-[9999] overflow-hidden">
            {/* Cutout Mask using SVG */}
            <svg className="absolute inset-0 w-full h-full pointer-events-none transition-all duration-500">
                <defs>
                    <mask id="tour-mask">
                        <rect x="0" y="0" width="100%" height="100%" fill="white" />
                        <rect 
                            x={targetRect.left - 8} 
                            y={targetRect.top - 8} 
                            width={targetRect.width + 16} 
                            height={targetRect.height + 16} 
                            rx="12" 
                            fill="black" 
                        />
                    </mask>
                </defs>
                <rect x="0" y="0" width="100%" height="100%" fill="rgba(0,0,0,0.6)" mask="url(#tour-mask)" />
            </svg>

            {/* Pulsing Border around target */}
            <div 
                className="absolute rounded-xl pointer-events-none transition-all duration-300 border-4 border-indigo-400/80 shadow-[0_0_30px_rgba(99,102,241,0.6)] animate-pulse"
                style={{
                    top: targetRect.top - 8,
                    left: targetRect.left - 8,
                    width: targetRect.width + 16,
                    height: targetRect.height + 16
                }}
            >
                {/* Dynamic Smart Hand */}
                <div className={handClass} style={handStyle}>
                    {handEmoji}
                </div>
            </div>

            {/* Tooltip Card */}
            <div 
                className="absolute bg-white p-6 rounded-2xl shadow-2xl w-80 animate-[float_3s_ease-in-out_infinite] border-2 border-indigo-100 flex flex-col gap-4 transition-all duration-300"
                style={tooltipStyle}
            >
                <div className="flex items-start gap-3">
                    <div className="w-10 h-10 rounded-full bg-indigo-100 flex items-center justify-center text-xl shrink-0">
                        {stepIndex === 0 ? '👋' : stepIndex === steps.length - 1 ? '🎉' : '💡'}
                    </div>
                    <div>
                        <h3 className="text-base font-bold text-slate-800 mb-1.5">{currentStep.title}</h3>
                        <p className="text-sm text-slate-500 leading-relaxed">{currentStep.content}</p>
                    </div>
                </div>

                {/* Progress Dots */}
                <div className="flex items-center justify-center gap-1.5 my-1">
                    {steps.map((_, i) => (
                        <div key={i} className={`h-1.5 rounded-full transition-all ${i === stepIndex ? 'w-6 bg-indigo-500' : 'w-1.5 bg-slate-200'}`}></div>
                    ))}
                </div>

                <div className="flex items-center justify-between pt-2 border-t border-slate-100">
                    <button onClick={onSkip} className="text-xs font-bold text-slate-400 hover:text-slate-600 px-2 py-1">跳過教學</button>
                    <button 
                        onClick={onNext} 
                        className="bg-indigo-600 text-white px-5 py-2 rounded-xl text-sm font-bold shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center gap-2 group"
                    >
                        {stepIndex === steps.length - 1 ? '開始使用！' : '下一步'} 
                        <i className="fa-solid fa-arrow-right group-hover:translate-x-1 transition-transform"></i>
                    </button>
                </div>
            </div>
        </div>
    );
};

// --- Main App ---
const App: React.FC = () => {
  const [cards, setCards] = useState<BusinessCardData[]>([]);
  const [selectedCardId, setSelectedCardId] = useState<string | null>(null);

  // Form State for Editing
  const [formData, setFormData] = useState<BusinessCardData | null>(null);
  const [isFormDirty, setIsFormDirty] = useState(false);

  const [tasks, setTasks] = useState<ProcessingTask[]>([]);
  const [viewMode, setViewMode] = useState<ViewMode>('file');
  const [isProcessing, setIsProcessing] = useState(false);
  const [isMobile, setIsMobile] = useState(window.innerWidth < 768);
  const [activeCategory, setActiveCategory] = useState<'employer' | 'academic' | 'staff' | 'other'>('employer');
  const [searchQuery, setSearchQuery] = useState('');
  const [isExporting, setIsExporting] = useState(false);
  const [isQueuePaused, setIsQueuePaused] = useState(false);
  const [isDragOver, setIsDragOver] = useState(false);

  // Background Task State (Non-blocking)
  const [bgTaskCount, setBgTaskCount] = useState(0);

  // Menu States
  const [showExportMenu, setShowExportMenu] = useState(false);
  const [showSettingsMenu, setShowSettingsMenu] = useState(false);
  const [showShareMenu, setShowShareMenu] = useState(false); // New state for Share
  const [showMobileUploadHint, setShowMobileUploadHint] = useState(false);

  // Onboarding State
  const [tourStepIndex, setTourStepIndex] = useState<number>(-1);

  // Refs
  const filesMap = useRef<Map<string, File | Blob>>(new Map());
  const tasksRef = useRef<ProcessingTask[]>([]);
  const processingMutex = useRef(false);
  const pausedRef = useRef(false);
  const dragCounter = useRef(0); // Add Drag Counter to prevent flickering

  const fileInputRef = useRef<HTMLInputElement>(null);
  const exportMenuRef = useRef<HTMLDivElement>(null);
  const settingsMenuRef = useRef<HTMLDivElement>(null);
  const shareMenuRef = useRef<HTMLDivElement>(null); // New ref for Share

  // Cropper States
  const [cropperImage, setCropperImage] = useState<string | null>(null);
  const [cropRegions, setCropRegions] = useState<CropRegion[]>([]);
  const [isDrawing, setIsDrawing] = useState(false);
  const [isMoving, setIsMoving] = useState(false);
  const [isResizing, setIsResizing] = useState<string | null>(null); 
  const [activeCropId, setActiveCropId] = useState<string | null>(null);
  const [startPos, setStartPos] = useState({ x: 0, y: 0 });
  const [initialRect, setInitialRect] = useState<CropRegion | null>(null);
  const [currentRect, setCurrentRect] = useState<CropRegion | null>(null);
  const cropperImgRef = useRef<HTMLImageElement>(null);
  const [pdfDoc, setPdfDoc] = useState<any>(null);
  const [currentPdfPage, setCurrentPdfPage] = useState(1);
  const [isRenderingPdf, setIsRenderingPdf] = useState(false);
  const [isAiDetecting, setIsAiDetecting] = useState(false);

  // Cropper Pan/Zoom
  const [cropperTransform, setCropperTransform] = useState({ scale: 1, x: 0, y: 0 });
  const [isCropperPanning, setIsCropperPanning] = useState(false);
  const cropperDragStart = useRef({ x: 0, y: 0 });

  // Computed Values
  const activeTasks = useMemo(() => tasks, [tasks]);

  const visibleCards = useMemo(() => {
    return cards.filter(c => {
      // Category Filter
      if (c.category !== activeCategory) return false;

      // Search Filter
      if (searchQuery) {
        const q = searchQuery.toLowerCase().trim();
        return (
          (c.firstName && c.firstName.toLowerCase().includes(q)) ||
          (c.lastName && c.lastName.toLowerCase().includes(q)) ||
          (c.company && c.company.toLowerCase().includes(q)) ||
          (c.email && c.email.toLowerCase().includes(q)) ||
          (c.phone && c.phone.toLowerCase().includes(q))
        );
      }
      return true;
    });
  }, [cards, activeCategory, searchQuery]);

  useEffect(() => { tasksRef.current = tasks; }, [tasks]);
  useEffect(() => { pausedRef.current = isQueuePaused; }, [isQueuePaused]);

  // --- Background Summary Generator (Batch Mode) ---
  const runBackgroundSummaryCheck = useCallback(async (cardsToCheck: BusinessCardData[]) => {
    const missingSummary = cardsToCheck.filter(c => !c.summary || c.summary.trim() === '');

    if (missingSummary.length > 0) {
        console.log(`Found ${missingSummary.length} cards without summary. Auto-generating in background (Batch Mode)...`);
        setBgTaskCount(missingSummary.length);

        // Process in chunks of 5 to balance latency and batch efficiency
        const chunkSize = 5;

        const process = async () => {
             for (let i = 0; i < missingSummary.length; i += chunkSize) {
                const chunk = missingSummary.slice(i, i + chunkSize);

                try {
                    // Generate summaries for the whole chunk
                    const summaries = await generateBatchSummaries(chunk);

                    // Update DB and State for each processed item
                    for (const result of summaries) {
                        const originalCard = chunk.find(c => c.id === result.id);
                        if (originalCard && result.summary) {
                            const updatedCard = { ...originalCard, summary: result.summary };
                            await saveCardToDB(updatedCard);

                            // Update state
                            setCards(prev => prev.map(c => c.id === updatedCard.id ? { ...c, summary: result.summary } : c));
                            setFormData(prev => prev && prev.id === updatedCard.id ? { ...prev, summary: result.summary } : prev);
                        }
                    }

                    // Brief pause to be gentle on rate limits
                    await new Promise(r => setTimeout(r, 1000));

                } catch (e) {
                    console.warn(`Failed to process batch summary chunk`, e);
                } finally {
                    setBgTaskCount(prev => Math.max(0, prev - chunk.length));
                }
            }
        };

        // Fire and forget
        process();
    }
  }, []);

  useEffect(() => {
    const handleResize = () => setIsMobile(window.innerWidth < 768);
    const handleClickOutside = (event: MouseEvent) => {
        if (exportMenuRef.current && !exportMenuRef.current.contains(event.target as Node)) {
            setShowExportMenu(false);
        }
        if (settingsMenuRef.current && !settingsMenuRef.current.contains(event.target as Node)) {
            setShowSettingsMenu(false);
        }
        if (shareMenuRef.current && !shareMenuRef.current.contains(event.target as Node)) {
            setShowShareMenu(false);
        }
    };
    window.addEventListener('resize', handleResize);
    document.addEventListener('mousedown', handleClickOutside);

    // Initial Load
    const loadInitialData = async () => {
      const savedCards = await getCardsMetadataFromDB();
      if (savedCards && savedCards.length > 0) {
        setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
        // Run auto-summary check in background (Sequentially)
        runBackgroundSummaryCheck(savedCards);
      }

      // Check Onboarding
      const hasVisited = localStorage.getItem('qs_scanner_v1_visited');
      if (!hasVisited) {
          // Brief delay to ensure render
          setTimeout(() => setTourStepIndex(0), 1000); // Increased delay for better initial impression
      }
    };
    loadInitialData();
    return () => {
        window.removeEventListener('resize', handleResize);
        document.removeEventListener('mousedown', handleClickOutside);
    };
  }, [runBackgroundSummaryCheck]);

  // Load selected card into form
  useEffect(() => {
    if (selectedCardId) {
      getCardById(selectedCardId).then(data => {
        if (data) {
             setFormData(data);
             setIsFormDirty(false);
        }
      });
    } else {
      setFormData(null);
      setIsFormDirty(false);
    }
  }, [selectedCardId]);

  // Save functionality
  const handleSave = async () => {
      if (!formData) return;
      await saveCardToDB(formData);
      // Update local list without re-fetching everything
      setCards(prev => prev.map(c => c.id === formData.id ? { ...c, ...formData } : c));
      setIsFormDirty(false);
      // Optional: Show a subtle toast
      const btn = document.getElementById('save-btn');
      if (btn) {
          const originalText = btn.innerHTML;
          btn.innerHTML = '<i class="fa-solid fa-check"></i>';
          setTimeout(() => btn.innerHTML = originalText, 2000);
      }
  };

  const updateField = (field: keyof BusinessCardData, value: string) => {
      if (!formData) return;
      setFormData({ ...formData, [field]: value });
      setIsFormDirty(true);
  };

  // --- Async Queue Logic ---
  const performSingleTask = async (task: ProcessingTask) => {
    try {
        const fileObj = filesMap.current.get(task.id);
        if (!fileObj) throw new Error("File missing from memory");

        const processWithTimeout = async () => {
            const base64Data = await compressImage(fileObj);
            const info = await extractCardInfo(base64Data, 'image/jpeg');
            return { base64Data, info };
        };

        const timeoutPromise = new Promise<{base64Data: string, info: any}>((_, reject) => 
            setTimeout(() => reject(new Error("Timeout (45s)")), 45000)
        );

        const { base64Data, info } = await Promise.race([processWithTimeout(), timeoutPromise]);

        const newCard: BusinessCardData = {
            notes: '',
            prefix: '',
            fax: '', // Initialize fax
            summary: '', // Initialize summary
            reasoning: '', // Initialize reasoning
            ...info,
            id: task.id,
            scannedAt: Date.now(),
            source: 'QS Hub Scanner',
            imageUrl: `data:image/jpeg;base64,${base64Data}`,
        };

        await saveCardToDB(newCard);
        const { imageUrl, ...newCardMeta } = newCard;
        setCards(prev => [newCardMeta as BusinessCardData, ...prev].sort((a,b) => b.scannedAt - a.scannedAt));

        // Mark as completed, wait 1.5s then remove from queue
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'completed', progress: 100 } : t));
        filesMap.current.delete(task.id);

        setTimeout(() => {
            setTasks(prev => prev.filter(t => t.id !== task.id));
        }, 1500);

    } catch (err: any) {
        console.error(`Task ${task.id} Failed:`, err);
        let errorMsg = err.message || "處理失敗";
        if (errorMsg.includes('500') || errorMsg.includes('Internal')) errorMsg = "伺服器錯誤 (500)";
        if (errorMsg.includes('Timeout')) errorMsg = "AI 回應超時";
        setTasks(prev => prev.map(t => t.id === task.id ? { ...t, status: 'error', error: errorMsg } : t));
    }
  };

  const processQueue = useCallback(async () => {
    if (processingMutex.current || pausedRef.current) return;
    processingMutex.current = true;
    setIsProcessing(true);
    try {
        while (true) {
            if (pausedRef.current) break;
            const nextTask = tasksRef.current.find(t => t.status === 'pending');
            if (!nextTask) break;
            setTasks(prev => prev.map(t => t.id === nextTask.id ? { ...t, status: 'processing' } : t));
            await performSingleTask(nextTask);
            await new Promise(r => setTimeout(r, 500));
        }
    } finally {
        processingMutex.current = false;
        setIsProcessing(false);
    }
  }, []);

  useEffect(() => {
    if (!isQueuePaused && !isProcessing) {
        processQueue();
    }
  }, [tasks, isQueuePaused, isProcessing, processQueue]);

  // --- Handlers ---
  const handleRetryTask = (taskId: string) => {
    setTasks(prev => prev.map(t => {
        if (t.id === taskId) {
            // Reset to pending so the queue processor picks it up again
            return { ...t, status: 'pending', error: undefined };
        }
        return t;
    }));
  };

  const handleDeleteCard = async (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    if (!window.confirm("確定要刪除這筆名片資料嗎？")) return;
    await deleteCardFromDB(id);
    setCards(prev => prev.filter(c => c.id !== id));
    if (selectedCardId === id) {
      setSelectedCardId(null);
      setFormData(null);
      setViewMode('file');
    }
  };

  const handleClearAll = async () => {
    if (cards.length === 0) return;
    if (!window.confirm("⚠️ 警告：這將會永久刪除所有紀錄！此動作無法復原。")) return;
    const success = await clearAllCardsFromDB();
    if (success) {
      setCards([]);
      setSelectedCardId(null);
      setFormData(null);
      setViewMode('file');
    }
  };

  // --- Mobile Share Handler ---
  const handleShare = async (withSummary: boolean) => {
      if (!formData) return;

      let shareText = '';

      if (withSummary && formData.summary) {
          shareText += `${formData.summary}\n\n`;
      }

      shareText += `姓名: ${formData.lastName}${formData.firstName}\n` +
          `公司: ${formData.company}\n` +
          `職稱: ${formData.title}\n` +
          (formData.phone ? `電話: ${formData.phone}\n` : '') +
          (formData.email ? `信箱: ${formData.email}\n` : '');

      if (withSummary && formData.summary) {
          shareText += `\n(⚠️ AI 生成說明僅供參考，請務必查證)`;
      }

      if (navigator.share) {
          try {
              await navigator.share({
                  title: `${formData.firstName} ${formData.lastName}`,
                  text: shareText
              });
          } catch (err) {
              console.warn('Share cancelled or failed', err);
          }
      } else {
          navigator.clipboard.writeText(shareText);
          alert("已複製到剪貼簿");
      }
  };

  const handleExport = async (mode: ExportMode) => {
    let targetCardsMetadata: BusinessCardData[] = [];

    // Determine Target Cards (Metadata only initially)
    if (mode === 'single') {
        if (!formData) return;
        targetCardsMetadata = [formData];
    } else if (mode === 'employer') {
        targetCardsMetadata = cards.filter(c => c.category === 'employer');
    } else if (mode === 'academic') {
        targetCardsMetadata = cards.filter(c => c.category === 'academic');
    } else if (mode === 'staff') {
        targetCardsMetadata = cards.filter(c => c.category === 'staff');
    } else {
        targetCardsMetadata = cards;
    }

    if (targetCardsMetadata.length === 0) { alert("無符合資料可匯出"); return; }

    setIsExporting(true);
    setShowExportMenu(false);

    try {
        const fullCards = await Promise.all(
            targetCardsMetadata.map(async (meta) => {
                if (mode === 'single' && formData && formData.id === meta.id && formData.imageUrl) {
                    return formData;
                }
                const fullData = await getCardById(meta.id);
                return fullData || meta; 
            })
        );

        if (mode === 'json' || mode === 'full_backup') {
            const jsonString = JSON.stringify(fullCards, null, 2);
            const blob = new Blob([jsonString], { type: "application/json" });
            const url = URL.createObjectURL(blob);
            const a = document.createElement('a');
            a.href = url;
            a.download = mode === 'full_backup' 
                ? `QS_FULL_BACKUP_${new Date().toISOString().split('T')[0]}.json`
                : `QS_Export_JSON_${new Date().toISOString().split('T')[0]}.json`;
            document.body.appendChild(a);
            a.click();
            document.body.removeChild(a);
            URL.revokeObjectURL(url);
            return;
        }

        const excelFile = await createExcelFile(fullCards, mode);
        const url = URL.createObjectURL(excelFile);
        const a = document.createElement('a');
        a.href = url; a.download = excelFile.name;
        document.body.appendChild(a); a.click(); document.body.removeChild(a); URL.revokeObjectURL(url);

    } catch (err: any) { 
        alert("匯出失敗：" + err.message); 
    } finally { 
        setIsExporting(false); 
    }
  };

  const processFiles = async (files: FileList | null) => {
    if (!files || files.length === 0) return;

    // JSON Restore
    if (files.length === 1 && files[0].name.toLowerCase().endsWith('.json')) {
        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const jsonStr = e.target?.result as string;
                const data = JSON.parse(jsonStr);
                const items = Array.isArray(data) ? data : [data];
                let count = 0;
                const importedItems: BusinessCardData[] = [];

                for (const item of items) {
                    // Update validation logic to allow cards with Company name even if Name is empty (General Cards)
                    if (item.id && (item.firstName || item.lastName || item.company)) {
                        // Phone Normalization for Restore (Programmatic logic, same as extraction)
                        if (item.phone && typeof item.phone === 'string') {
                            item.phone = item.phone.split('/')
                                .map((p: string) => p.replace(/[-\s]/g, ''))
                                .filter((p: string) => p.length > 0)
                                .join(' / ');
                        }
                        // Fax Normalization for Restore
                        if (item.fax && typeof item.fax === 'string') {
                            item.fax = item.fax.split('/')
                                .map((p: string) => p.replace(/[-\s]/g, ''))
                                .filter((p: string) => p.length > 0)
                                .join(' / ');
                        } else if (!item.fax) {
                            item.fax = '';
                        }

                        await saveCardToDB(item as BusinessCardData);
                        importedItems.push(item as BusinessCardData);
                        count++;
                    }
                }
                alert(`成功從 JSON 備份還原 ${count} 筆資料 (含圖片)！`);
                const savedCards = await getCardsMetadataFromDB();
                setCards(savedCards.sort((a, b) => b.scannedAt - a.scannedAt));
                setShowMobileUploadHint(false);

                // Run background summary generation on imported items
                runBackgroundSummaryCheck(importedItems);

            } catch (err) {
                console.error(err);
                alert("JSON 還原失敗：檔案格式錯誤");
            } finally {
                if (fileInputRef.current) fileInputRef.current.value = '';
            }
        };
        reader.readAsText(files[0]);
        return;
    }

    // Legacy Excel Check
    if (files.length === 1 && files[0].name.endsWith('.xlsx')) {
        alert("⚠️ 錯誤：系統不再支援 Excel 還原備份。\n請使用 .json 格式的備份檔以確保圖片能正確恢復。");
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    const firstFile = files[0];

    // PDF / Single Image for Cropper
    if (firstFile.type === 'application/pdf') {
        const reader = new FileReader();
        reader.onload = async (ev) => {
            const typedarray = new Uint8Array(ev.target?.result as ArrayBuffer);
            try {
                const pdf = await pdfjs.getDocument(typedarray).promise;
                setPdfDoc(pdf); setCurrentPdfPage(1); await renderPdfPage(pdf, 1);
                setViewMode('cropper');
                setShowMobileUploadHint(false);
            } catch (err) { alert("PDF 解析失敗"); }
        };
        reader.readAsArrayBuffer(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        return;
    }

    if (files.length === 1 && firstFile.type.startsWith('image/')) {
        const reader = new FileReader();
        reader.onload = (event) => {
            const b64 = event.target?.result as string;
            setCropperImage(b64); setCropRegions([]); setViewMode('cropper'); setCropperTransform({scale:1, x:0, y:0});
            autoDetectInCropper(b64.split(',')[1]);
        };
        reader.readAsDataURL(firstFile);
        if (fileInputRef.current) fileInputRef.current.value = '';
        setShowMobileUploadHint(false);
        return;
    }

    // Batch Processing
    const newTasks: ProcessingTask[] = [];
    for (const f of Array.from(files) as File[]) {
      if (!f.type.startsWith('image/')) continue;
      const id = crypto.randomUUID();
      filesMap.current.set(id, f);
      const previewUrl = URL.createObjectURL(f);
      newTasks.push({ id, fileName: f.name, status: 'pending', progress: 0, batchIndex: 1, previewUrl });
    }
    setTasks(prev => [...prev, ...newTasks]);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setShowMobileUploadHint(false);
  };

  // Drag & Drop
  const handleDragEnter = (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      dragCounter.current++;
      if (e.dataTransfer.items && e.dataTransfer.items.length > 0) {
          setIsDragOver(true);
      }
  };

  const handleDragLeave = (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      dragCounter.current--;
      if (dragCounter.current <= 0) {
          setIsDragOver(false);
          dragCounter.current = 0; // ensure reset
      }
  };

  const handleDragOver = (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
  };

  const handleDrop = (e: React.DragEvent) => {
      e.preventDefault();
      e.stopPropagation();
      setIsDragOver(false);
      dragCounter.current = 0;
      processFiles(e.dataTransfer.files);
  };

  // --- Cropper Functions ---
  const autoDetectInCropper = async (b64: string) => {
    setIsAiDetecting(true);
    try {
      const boxes = await detectBusinessCards(b64);
      setCropRegions(boxes.map(box => ({
        id: crypto.randomUUID(), x: (box.xmin/1000)*100, y: (box.ymin/1000)*100, w: ((box.xmax-box.xmin)/1000)*100, h: ((box.ymax-box.ymin)/1000)*100
      })));
    } catch (e) { console.warn(e); } finally { setIsAiDetecting(false); }
  };

  const renderPdfPage = async (pdf: any, pageNum: number) => {
    setIsRenderingPdf(true);
    try {
        const page = await pdf.getPage(pageNum);
        const viewport = page.getViewport({ scale: 2 });
        const canvas = document.createElement('canvas');
        canvas.height = viewport.height; canvas.width = viewport.width;
        const context = canvas.getContext('2d');
        if (context) {
            await page.render({ canvasContext: context, viewport }).promise;
            const b64 = canvas.toDataURL('image/jpeg');
            setCropperImage(b64); setCropRegions([]); setCropperTransform({scale:1, x:0, y:0});
            autoDetectInCropper(b64.split(',')[1]);
        }
    } catch (e) { alert("無法讀取 PDF"); } finally { setIsRenderingPdf(false); }
  };

  // Cropper Pan & Zoom Handlers
  const handleCropperWheel = (e: React.WheelEvent) => {
      e.preventDefault();
      const scaleChange = -e.deltaY * 0.001;
      setCropperTransform(prev => ({
          ...prev,
          scale: Math.min(Math.max(0.5, prev.scale + scaleChange), 5)
      }));
  };

  const handleCropperMouseDown = (e: React.MouseEvent) => {
      // Only pan if we are NOT clicking a crop region or a handle
      const target = e.target as HTMLElement;
      if (target.closest('.crop-box') || isDrawing || isMoving || isResizing) return;

      setIsCropperPanning(true);
      cropperDragStart.current = { x: e.clientX - cropperTransform.x, y: e.clientY - cropperTransform.y };
  };

  const handleCropperMouseMove = (e: React.MouseEvent | React.TouchEvent) => {
      let clientX: number, clientY: number;

      if ('touches' in e) {
          if (e.touches.length === 0) return;
          clientX = e.touches[0].clientX;
          clientY = e.touches[0].clientY;
      } else {
          clientX = (e as React.MouseEvent).clientX;
          clientY = (e as React.MouseEvent).clientY;
      }

      if (isCropperPanning) {
          if (e.cancelable) e.preventDefault();
          setCropperTransform(prev => ({
              ...prev,
              x: clientX - cropperDragStart.current.x,
              y: clientY - cropperDragStart.current.y
          }));
          return;
      }
      handleCropMove(e); // Delegate to crop logic if not panning
  };

  const handleCropperMouseUp = () => {
      setIsCropperPanning(false);
      handleCropEnd();
  };

  // Crop Logic (Coordinate Calculation)
  const getMousePos = (e: React.MouseEvent | React.TouchEvent) => {
      if (!cropperImgRef.current) return { x: 0, y: 0 };
      const rect = cropperImgRef.current.getBoundingClientRect();
      const clientX = 'touches' in e ? e.touches[0].clientX : (e as React.MouseEvent).clientX;
      const clientY = 'touches' in e ? e.touches[0].clientY : (e as React.MouseEvent).clientY;

      // Calculate position relative to the SCALED image
      return { 
          x: ((clientX - rect.left) / rect.width) * 100, 
          y: ((clientY - rect.top) / rect.height) * 100 
      };
  };

  const handleCropStart = (e: React.MouseEvent | React.TouchEvent, action: 'draw' | 'move' | 'resize' = 'draw', cropId?: string, handle?: string) => {
      // If pressing controls, don't trigger draw
      e.stopPropagation(); 
      const pos = getMousePos(e); setStartPos(pos);
      if (action === 'draw') { setCurrentRect({ id: 'temp', x: pos.x, y: pos.y, w: 0, h: 0 }); setIsDrawing(true); setActiveCropId(null); }
      else if (action === 'move' && cropId) { const crop = cropRegions.find(r => r.id === cropId); if (crop) { setInitialRect({ ...crop }); setIsMoving(true); setActiveCropId(cropId); } }
      else if (action === 'resize' && cropId && handle) { const crop = cropRegions.find(r => r.id === cropId); if (crop) { setInitialRect({ ...crop }); setIsResizing(handle); setActiveCropId(cropId); } }
  };

  const handleCropMove = (e: React.MouseEvent | React.TouchEvent) => {
      if (!isDrawing && !isMoving && !isResizing) return;
      const pos = getMousePos(e);
      if (isDrawing && currentRect) { setCurrentRect({ ...currentRect, x: Math.min(pos.x, startPos.x), y: Math.min(pos.y, startPos.y), w: Math.abs(pos.x - startPos.x), h: Math.abs(pos.y - startPos.y) }); }
      else if (isMoving && activeCropId && initialRect) { setCropRegions(prev => prev.map(r => r.id === activeCropId ? { ...r, x: Math.max(0, Math.min(100 - r.w, initialRect.x + (pos.x - startPos.x))), y: Math.max(0, Math.min(100 - r.h, initialRect.y + (pos.y - startPos.y))) } : r)); }
      else if (isResizing && activeCropId && initialRect) { 
          const dx = pos.x - startPos.x; const dy = pos.y - startPos.y;
          setCropRegions(prev => prev.map(r => {
              if (r.id !== activeCropId) return r;
              let { x, y, w, h } = initialRect;
              if (isResizing.includes('t')) { const newY = Math.max(0, y + dy); h = h + (y - newY); y = newY; }
              if (isResizing.includes('b')) { h = Math.max(1, Math.min(100 - y, h + dy)); }
              if (isResizing.includes('l')) { const newX = Math.max(0, x + dx); w = w + (x - newX); x = newX; }
              if (isResizing.includes('r')) { w = Math.max(1, Math.min(100 - x, w + dx)); }
              return { ...r, x, y, w, h };
          })); 
      }
  };

  const handleCropEnd = () => {
      if (isDrawing && currentRect && currentRect.w > 2 && currentRect.h > 2) { const newCrop = { ...currentRect, id: crypto.randomUUID() }; setCropRegions(prev => [...prev, newCrop]); setActiveCropId(newCrop.id); }
      setIsDrawing(false); setIsMoving(false); setIsResizing(null); setCurrentRect(null);
  };

  const processCrops = async () => {
      if (!cropperImage || !cropperImgRef.current) return;
      const sourceImg = new Image(); sourceImg.src = cropperImage;
      await new Promise(r => sourceImg.onload = r);
      const newTasks: ProcessingTask[] = [];
      for (let i = 0; i < cropRegions.length; i++) {
          const crop = cropRegions[i];
          const canvas = document.createElement('canvas');
          canvas.width = (crop.w/100)*sourceImg.naturalWidth; canvas.height = (crop.h/100)*sourceImg.naturalHeight;
          const ctx = canvas.getContext('2d');
          if (ctx) {
              ctx.drawImage(sourceImg, (crop.x/100)*sourceImg.naturalWidth, (crop.y/100)*sourceImg.naturalHeight, canvas.width, canvas.height, 0, 0, canvas.width, canvas.height);
              const blob = await new Promise<Blob | null>(res => canvas.toBlob(res, 'image/jpeg', 0.95));
              if (blob) {
                  const id = crypto.randomUUID(); filesMap.current.set(id, blob);
                  newTasks.push({ id, fileName: `CROP_${i+1}.jpg`, status: 'pending', progress: 0, batchIndex: 1, previewUrl: URL.createObjectURL(blob) });
              }
          }
      }
      setTasks(prev => [...prev, ...newTasks]); setPdfDoc(null); setCropperImage(null); setViewMode('file');
  };

  const handleRotateCropImage = async (direction: 'left' | 'right') => {
      if (!cropperImage) return;

      const img = new Image();
      img.src = cropperImage;
      await new Promise(r => img.onload = r);

      const canvas = document.createElement('canvas');
      canvas.width = img.height;
      canvas.height = img.width;

      const ctx = canvas.getContext('2d');
      if (!ctx) return;

      ctx.translate(canvas.width / 2, canvas.height / 2);
      ctx.rotate(direction === 'right' ? 90 * Math.PI / 180 : -90 * Math.PI / 180);
      ctx.drawImage(img, -img.width / 2, -img.height / 2);

      const newB64 = canvas.toDataURL('image/jpeg', 0.95);

      setCropperImage(newB64);
      setCropRegions([]); 
      setCropperTransform({ scale: 1, x: 0, y: 0 }); 

      // Re-run AI detection on rotated image
      autoDetectInCropper(newB64.split(',')[1]);
  };

  const handleAddClick = () => {
      if (isMobile) {
          setShowMobileUploadHint(true);
      } else {
          fileInputRef.current?.click();
      }
  };

  // --- Onboarding Logic ---
  const tourSteps: TourStep[] = [
      {
          targetId: 'btn-upload',
          title: '開始第一步',
          content: '點擊此按鈕上傳名片圖片 (支援 JPG, PNG, PDF)，或使用相機拍照。',
          position: isMobile ? 'bottom-left' : 'right'
      },
      {
          targetId: 'btn-search',
          title: '資料庫搜尋',
          content: '點擊這裡進入全螢幕資料庫，您可以進行篩選、排序或搜尋特定名片。',
          position: 'bottom-left'
      },
      {
          targetId: 'detail-panel',
          title: '名片詳情與 AI 分析',
          content: '當您選擇名片後，這裡會顯示完整資訊。您可以編輯任何欄位，並查看 AI 提供的分類理由摘要。',
          position: 'left'
      },
      {
          targetId: 'btn-export',
          title: '匯出資料',
          content: '這裡可以將掃描好的資料匯出成 QS 格式、Excel 或備份檔。',
          position: 'bottom-right'
      },
      {
          targetId: 'btn-settings',
          title: '系統設定',
          content: '設定 API 金鑰或清除所有資料（危險區域）都在這裡。',
          position: 'bottom-right'
      }
  ];

  const handleTourNext = () => {
      if (tourStepIndex < tourSteps.length - 1) {
          setTourStepIndex(prev => prev + 1);
      } else {
          setTourStepIndex(-1);
          localStorage.setItem('qs_scanner_v1_visited', 'true');
      }
  };

  const handleTourSkip = () => {
      setTourStepIndex(-1);
      localStorage.setItem('qs_scanner_v1_visited', 'true');
  };

  // --- Render ---
  return (
    <div className="flex h-screen w-full bg-slate-50 text-slate-900 font-sans overflow-hidden" 
         onDragEnter={handleDragEnter} 
         onDragLeave={handleDragLeave} 
         onDragOver={handleDragOver} 
         onDrop={handleDrop}>
      {/* Remove .xlsx from accept to prevent confusion */}
      <input type="file" ref={fileInputRef} className="hidden" accept=".jpg, .jpeg, .png, .heic, .pdf, .json" multiple onChange={(e) => processFiles(e.target.files)} />

      {/* Onboarding Tour */}
      {tourStepIndex >= 0 && (
          <TourOverlay 
            stepIndex={tourStepIndex} 
            steps={tourSteps} 
            onNext={handleTourNext} 
            onSkip={handleTourSkip} 
          />
      )}

      {/* Mobile Upload Hint Modal */}
      {showMobileUploadHint && (
          <div className="fixed inset-0 z-[1000] bg-black/60 backdrop-blur-sm flex items-center justify-center p-6 animate-fadeIn">
              <div className="bg-white w-full max-w-sm rounded-2xl shadow-2xl p-6 text-center">
                  <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-4">
                      <i className="fa-solid fa-cloud-arrow-up text-2xl"></i>
                  </div>
                  <h3 className="text-lg font-bold text-slate-800 mb-2">上傳檔案</h3>
                  <p className="text-sm text-slate-500 mb-6 leading-relaxed">
                      請選擇檔案進行上傳。<br/>支援 <b>JPG, PNG, PDF</b> 圖片掃描<br/>或 <b>JSON</b> 備份還原。
                  </p>
                  <div className="flex flex-col gap-3">
                      <button onClick={() => fileInputRef.current?.click()} className="w-full py-3 bg-indigo-600 text-white rounded-xl font-bold shadow-lg shadow-indigo-200 active:scale-95 transition-all">
                          選擇檔案
                      </button>
                      <button onClick={() => setShowMobileUploadHint(false)} className="w-full py-3 text-slate-400 font-bold hover:text-slate-600">
                          取消
                      </button>
                  </div>
              </div>
          </div>
      )}

      {/* Drag & Drop Overlay */}
      {isDragOver && (
          <div className="fixed inset-0 z-[1000] bg-indigo-600/95 backdrop-blur-sm flex items-center justify-center animate-fadeIn">
              <div className="text-white text-center px-6">
                  <i className="fa-solid fa-cloud-arrow-up text-6xl mb-6 animate-bounce"></i>
                  <h2 className="text-2xl font-bold mb-4">釋放以匯入檔案</h2>
                  <div className="grid grid-cols-2 gap-4 max-w-sm mx-auto text-left">
                      <div className="bg-white/10 p-3 rounded-lg border border-white/20">
                          <h3 className="font-bold text-sm mb-1"><i className="fa-regular fa-image mr-2"></i>名片掃描</h3>
                          <p className="text-xs opacity-70">支援 JPG, PNG, PDF 圖片檔</p>
                      </div>
                      <div className="bg-white/10 p-3 rounded-lg border border-white/20">
                          <h3 className="font-bold text-sm mb-1"><i className="fa-solid fa-rotate mr-2"></i>資料還原</h3>
                          <p className="text-xs opacity-70">僅支援 JSON 完整備份檔</p>
                      </div>
                  </div>
                  <p className="mt-8 text-xs font-mono opacity-50 bg-black/20 inline-block px-3 py-1 rounded">不支援 Excel (.xlsx) 還原</p>
              </div>
          </div>
      )}

      {/* --- LEFT SIDEBAR (Navigation & List) --- */}
      <aside className={`${isMobile && viewMode !== 'file' ? 'hidden' : 'flex'} w-full md:w-[320px] lg:w-[380px] flex-row bg-white border-r border-slate-200 shadow-xl lg:shadow-none z-10 shrink-0`}>

         {/* 1. Left Task Rail (Queue & Quick Action) */}
         <div className="w-[64px] bg-slate-50 border-r border-slate-200 flex flex-col items-center py-4 gap-3 shrink-0 z-20">
             {/* Add Button - Updated Handler */}
             <button id="btn-upload" onClick={handleAddClick} className="w-10 h-10 rounded-xl bg-indigo-600 text-white shadow-lg shadow-indigo-200 hover:bg-indigo-700 active:scale-95 transition-all flex items-center justify-center" title="上傳名片">
                 <i className="fa-solid fa-plus text-sm"></i>
             </button>

             {/* Divider */}
             <div className="w-6 h-px bg-slate-200 my-1"></div>

             {/* Task List */}
             <div className="flex-1 w-full overflow-y-auto custom-scrollbar flex flex-col items-center gap-2 px-1 pb-4">
                 {activeTasks.map(task => (
                     <div 
                         key={task.id} 
                         className={`relative w-10 h-10 rounded-lg bg-white border border-slate-200 shadow-sm shrink-0 overflow-hidden group transition-all ${task.status === 'error' ? 'cursor-pointer hover:ring-2 hover:ring-red-400' : 'cursor-help'}`}
                         onClick={() => task.status === 'error' && handleRetryTask(task.id)}
                     >
                         {task.previewUrl ? (
                             <img src={task.previewUrl} className="w-full h-full object-cover opacity-80" />
                         ) : (
                             <div className="w-full h-full flex items-center justify-center text-slate-300"><i className="fa-solid fa-image"></i></div>
                         )}
                         {task.status === 'processing' && (
                             <div className="absolute inset-0 bg-black/40 flex items-center justify-center">
                                 <i className="fa-solid fa-circle-notch fa-spin text-white text-xs"></i>
                             </div>
                         )}
                         {task.status === 'completed' && (
                             <div className="absolute inset-0 bg-emerald-500/90 flex items-center justify-center animate-fadeIn">
                                 <i className="fa-solid fa-check text-white text-sm"></i>
                             </div>
                         )}
                         {task.status === 'error' && (
                             <div className="absolute inset-0 border-2 border-red-500 rounded-lg flex flex-col items-center justify-center bg-red-50/80 backdrop-blur-[1px] transition-colors hover:bg-red-100/80">
                                 <i className="fa-solid fa-rotate-right text-red-600 text-sm mb-0.5"></i>
                                 <span className="text-[6px] font-black text-red-600 leading-none">RETRY</span>
                             </div>
                         )}
                     </div>
                 ))}
             </div>
         </div>

         {/* 2. Right Sidebar Content */}
         <div className="flex-1 flex flex-col min-w-0 bg-white relative">
            <div className="p-4 border-b border-slate-100 bg-white sticky top-0 z-20" style={{paddingTop: isMobile ? 'calc(1rem + var(--sat))' : '1.5rem'}}>
                <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                        <div className="w-10 h-10 bg-slate-900 rounded-xl flex items-center justify-center text-white shadow-lg">
                            <i className="fa-solid fa-bahai text-lg animate-[spin_10s_linear_infinite]"></i>
                        </div>
                        <div>
                            <h1 className="text-lg font-black text-slate-900 tracking-tight leading-none">QS HUB</h1>
                            <div className="flex items-center gap-2 mt-0.5">
                                <span className="text-[10px] font-bold text-slate-400 tracking-widest">SCANNER PRO</span>
                                {bgTaskCount > 0 && (
                                    <div className="flex items-center gap-1.5 px-1.5 py-0.5 bg-indigo-50 rounded-md border border-indigo-100 animate-pulse">
                                        <i className="fa-solid fa-wand-magic-sparkles text-indigo-500 text-[9px]"></i>
                                        <span className="text-[9px] font-bold text-indigo-600">AI 補全中 ({bgTaskCount})</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>
                    <div className="flex items-center gap-1">
                        {/* Export Menu */}
                        <div className="relative" ref={exportMenuRef}>
                            <button id="btn-export" onClick={() => setShowExportMenu(!showExportMenu)} className={`w-8 h-8 flex items-center justify-center rounded-lg transition-colors ${showExportMenu ? 'bg-indigo-100 text-indigo-600' : 'text-slate-400 hover:text-indigo-600 hover:bg-indigo-50'}`} title="匯出選項">
                                <i className="fa-solid fa-file-export"></i>
                            </button>
                            {showExportMenu && (
                                <div className="absolute right-0 top-full mt-2 w-64 bg-white rounded-xl shadow-xl border border-slate-100 py-2 z-50 animate-fadeIn origin-top-right">
                                    {/* Group 1: QS Format */}
                                    <div className="px-4 py-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50/50">QS 格式匯出</div>
                                    <button onClick={() => handleExport('employer')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2">
                                        <i className="fa-solid fa-briefcase w-4 text-center text-slate-400"></i> QS Employer
                                    </button>
                                    <button onClick={() => handleExport('academic')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2">
                                        <i className="fa-solid fa-graduation-cap w-4 text-center text-slate-400"></i> QS Academic
                                    </button>
                                    <button onClick={() => handleExport('staff')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2">
                                        <i className="fa-solid fa-user-tag w-4 text-center text-slate-400"></i> QS Staff
                                    </button>

                                    {/* Group 2: Details */}
                                    <div className="px-4 py-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50/50 mt-1">名片詳情匯出</div>
                                    <button onClick={() => handleExport('all_clean')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2">
                                        <i className="fa-solid fa-language w-4 text-center text-slate-400"></i> 所有名片原文 (Excel)
                                    </button>
                                    <button onClick={() => handleExport('all_original')} className="w-full text-left px-4 py-2 text-sm text-slate-700 hover:bg-slate-50 hover:text-indigo-600 transition-colors flex items-center gap-2">
                                        <i className="fa-solid fa-database w-4 text-center text-slate-400"></i> 所有資料含註解 (Excel)
                                    </button>

                                    {/* Group 3: Backup */}
                                    <div className="px-4 py-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50/50 mt-1">備份</div>
                                    <button onClick={() => handleExport('full_backup')} className="w-full text-left px-4 py-2 text-sm text-indigo-700 bg-indigo-50/50 hover:bg-indigo-100 transition-colors flex items-center gap-2">
                                        <i className="fa-solid fa-cloud-arrow-down w-4 text-center"></i> 完整備份 (JSON - 含圖片)
                                    </button>
                                </div>
                            )}
                        </div>

                        {/* Settings Menu */}
                        <div className="relative" ref={settingsMenuRef}>
                            <button id="btn-settings" onClick={() => setShowSettingsMenu(!showSettingsMenu)} className={`w-8 h-8 flex items-center justify-center rounded-lg transition-colors ${showSettingsMenu ? 'bg-slate-100 text-slate-700' : 'text-slate-400 hover:text-slate-600 hover:bg-slate-50'}`} title="設定">
                                <i className="fa-solid fa-gear"></i>
                            </button>
                            {showSettingsMenu && (
                                <div className="absolute right-0 top-full mt-2 w-56 bg-white rounded-xl shadow-xl border border-slate-100 py-2 z-50 animate-fadeIn origin-top-right">
                                    <div className="px-4 py-1.5 text-[10px] font-bold text-slate-400 uppercase tracking-widest bg-slate-50/50">系統設定</div>

                                    {/* API Key setting button removed */}

                                    <button onClick={() => { setShowSettingsMenu(false); handleClearAll(); }} className="w-full text-left px-4 py-3 text-sm text-red-600 hover:bg-red-50 transition-colors flex items-center gap-2 font-bold">
                                        <i className="fa-solid fa-trash-can w-4 text-center"></i> 刪除所有資料
                                    </button>
                                </div>
                            )}
                        </div>

                    </div>
                </div>

                {isMobile && (
                    <div className="mb-4">
                        <button onClick={() => setViewMode('camera')} className="w-full flex items-center justify-center gap-2 py-3 bg-indigo-50 text-indigo-700 rounded-xl font-bold text-xs uppercase tracking-wide hover:bg-indigo-100 transition-colors">
                            <i className="fa-solid fa-camera"></i> 拍照
                        </button>
                    </div>
                )}

                {/* Search / Filter Area */}
                <div className="mb-3">
                    <button id="btn-search" onClick={() => setViewMode('search')} className="w-full flex items-center gap-3 bg-slate-100 rounded-lg px-3 py-2.5 text-xs text-slate-400 hover:bg-slate-200 transition-colors group">
