                                                    </label>
                                                    <span className={`text-xs font-bold px-2 py-0.5 rounded uppercase ${
                                                        formData.category === 'academic' ? 'bg-amber-100 text-amber-600' :
                                                        formData.category === 'staff' ? 'bg-emerald-100 text-emerald-600' :
                                                        formData.category === 'other' ? 'bg-slate-200 text-slate-600' :
                                                        'bg-blue-100 text-blue-600'
