                                                            key={cat}
                                                            onClick={() => updateField('category', cat)}
                                                            className={`flex-1 py-2 rounded-md text-sm font-bold uppercase transition-all flex items-center justify-center gap-2 ${
                                                                formData.category === cat
                                                                    ? 'bg-white text-indigo-600 shadow-sm ring-1 ring-black/5'
